#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/../../.."

[ -f spike/out/dev-record.md ] || { echo "GATE FAIL: spike/out/dev-record.md missing"; exit 1; }

FIRST_LINE=$(head -1 spike/out/dev-record.md)
[[ "$FIRST_LINE" =~ ^Persona:\ .+ ]] || { echo "GATE FAIL: first line does not match 'Persona: <name>'"; exit 1; }

HEADINGS=("## Status" "## Implementation artifacts" "## Gates" "## Findings and resolutions" "## Final diff size")
PREV_LINE=0
for h in "${HEADINGS[@]}"; do
  LINE=$(grep -n "^$h$" spike/out/dev-record.md | head -1 | cut -d: -f1)
  [ -n "$LINE" ] || { echo "GATE FAIL: heading '$h' not found"; exit 1; }
  [ "$LINE" -gt "$PREV_LINE" ] || { echo "GATE FAIL: heading '$h' not in required order"; exit 1; }
  NEXT_LINE=$((LINE + 1))
  [ "$NEXT_LINE" -le "$(wc -l < spike/out/dev-record.md)" ] || { echo "GATE FAIL: heading '$h' has no content after it"; exit 1; }
  sed -n "${NEXT_LINE}p" spike/out/dev-record.md | grep -q '[^[:space:]]' || { echo "GATE FAIL: heading '$h' followed only by blank line"; exit 1; }
  PREV_LINE=$LINE
done

echo "GATE PASS: T3 dev-record.md has correct structure"

